const schema = [{"@context":"https://schema.org","@type":"Service","name":"Permission &amp; metadata","serviceType":"Editorial service","provider":{"@type":"Organization","name":"Pubrica","url":"https://pubrica.com/"},"url":"https://pubrica.com/services/academic-editorial-services/permission-and-metadata-services/","description":"Permissions secured for third-party figures, tables and text, licences chosen, and metadata built for PubMed, Crossref, Scopus and DOAJ.","areaServed":"Worldwide","audience":{"@type":"Audience","audienceType":"Researchers, PhD scholars, research institutions, medical writers and life-science teams"}},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Why do I need permission for a figure or table?","acceptedAnswer":{"@type":"Answer","text":"Publishers require formal rights to use previously published content. Using it without permission can mean rejection, a correction after publication, or a legal claim.\n\nIt catches people out because the item often feels like yours — a figure you redrew, a table from a guideline, or your own figure from an earlier paper whose copyright you assigned on publication."}},{"@type":"Question","name":"Do you cover Creative Commons content?","acceptedAnswer":{"@type":"Answer","text":"Yes. We check whether CC-licensed material is free to use as you intend, or whether the licence requires attribution in a particular form, restricts modification, or forbids commercial reuse.\n\nThe attribution wording matters more than people expect. A CC licence that is satisfied incorrectly is not satisfied."}},{"@type":"Question","name":"Can you optimise metadata for indexing platforms?","acceptedAnswer":{"@type":"Answer","text":"Yes — PubMed, Crossref, Scopus, DOAJ and institutional repositories, each of which wants the information in a slightly different form.\n\nThe single biggest gain is usually keywords. Terms drawn from MeSH and absent from your title reach readers that title words cannot, because the title is already indexed."}},{"@type":"Question","name":"Who benefits from these services?","acceptedAnswer":{"@type":"Answer","text":"Academic researchers and scholars, journal and book authors, universities and research institutions, corporate R&D teams, publishers and editors, and NGOs, policy institutes and government research bodies.\n\nBook and monograph authors get the most out of it, because permissions loads there are large and the publisher’s deadline is usually fixed."}},{"@type":"Question","name":"What if a copyright holder refuses?","acceptedAnswer":{"@type":"Answer","text":"It happens, and it is not a crisis if there is time. We give you the options: replace the material, redraw the figure from the underlying data with a new caption, or cut it and adjust the text.\n\nWe do not choose for you, and we do not proceed on the assumption that a non-reply is a yes. It is not."}},{"@type":"Question","name":"How early should I start?","acceptedAnswer":{"@type":"Answer","text":"Earlier than feels necessary. Rights holders commonly take four to six weeks, some take longer, and a few never reply at all — and a non-reply needs the same plan as a refusal.\n\nSend the manuscript for the free audit as soon as the figures are settled. Knowing you have eleven items and six of them need requests is worth having before the submission date, not after."}}]},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pubrica.com/"},{"@type":"ListItem","position":2,"name":"Services","item":"https://pubrica.com/services/"},{"@type":"ListItem","position":3,"name":"Academic editorial","item":"https://pubrica.com/services/academic-editorial-services/permission-and-metadata-services/"}]}];

